{"Table":"vb_tb_dwellers","Create Table":"CREATE TABLE `vb_tb_dwellers` (\n  `id` varchar(36) NOT NULL,\n  `owner` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `name` varchar(100) NOT NULL,\n  `gender` char(1) NOT NULL,\n  `lvl` int(11) NOT NULL,\n  `father` varchar(255) DEFAULT NULL,\n  `mother` varchar(255) DEFAULT NULL,\n  `strength` int(11) NOT NULL,\n  `perception` int(11) NOT NULL,\n  `endurance` int(11) NOT NULL,\n  `charism` int(11) NOT NULL,\n  `intelligence` int(11) NOT NULL,\n  `agility` int(11) NOT NULL,\n  `luck` int(11) NOT NULL,\n  `serialized_id` int(6) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `idx_dwellers_attrb` (`id`,`strength`,`perception`,`endurance`,`charism`,`intelligence`,`agility`,`luck`),\n  KEY `idx_dwellers_father` (`id`,`father`),\n  KEY `idx_dwellers_mother` (`id`,`mother`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"vb_tb_dwellers.sql","path":"files/sql/rod/vb_tb_dwellers.sql","sha":"7068de2d7c8ff2ecec914f747d99b10f05a44918","size":106400,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/vb_tb_dwellers.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/vb_tb_dwellers.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/7068de2d7c8ff2ecec914f747d99b10f05a44918","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/vb_tb_dwellers.sql","type":"file","content":"eyJUYWJsZSI6InZiX3RiX2R3ZWxsZXJzIiwiQ3JlYXRlIFRhYmxlIjoiQ1JF\nQVRFIFRBQkxFIGB2Yl90Yl9kd2VsbGVyc2AgKFxuICBgaWRgIHZhcmNoYXIo\nMzYpIE5PVCBOVUxMLFxuICBgb3duZXJgIHZhcmNoYXIoMjU1KSBOT1QgTlVM\nTCxcbiAgYGNyZWF0ZWRfYXRgIHRpbWVzdGFtcCBOT1QgTlVMTCBERUZBVUxU\nIGN1cnJlbnRfdGltZXN0YW1wKCksXG4gIGB1cGRhdGVkX2F0YCB0aW1lc3Rh\nbXAgTk9UIE5VTEwgREVGQVVMVCBjdXJyZW50X3RpbWVzdGFtcCgpIE9OIFVQ\nREFURSBjdX